def diff(a,b):return float(Decimal(str(a))-Decimal(str(b)))
def records():
    assets=[];capacity=[]
    for code,name,stock,index,wear,renew,dispose in ASSETS:
        for i,y in enumerate(YEARS):
            assets.append(dict(code=code,title=name,year=y,stock_mrub=stock[i],volume_index=index if y==2024 else None,wear_pct=wear[i],renewal_pct=renew[i],disposal_pct=dispose[i],wear_change_pp=diff(wear[i],wear[i-1]) if i else None,source=SOURCE,tables="14.4; 14.6; 14.7",pages="302; 304–305"))
    for code,name,group,*values in CAPACITY:
        for i,y in enumerate(YEARS):
            u=values[i]
            if not 0<=u<=100:raise ValueError("Out of range capacity observation")
            capacity.append(dict(code=code,title=name,group=group,year=y,utilization_pct=u,unused_share_pct=diff(100,u),theoretical_extra_vs_output_pct=(100/u-1)*100 if u>0 else None,change_pp=diff(u,values[i-1]) if i and not (code=="condensed" and y==2023) else None,comparison_status="first_year" if not i else "definition_changed" if code=="condensed" and y==2023 else "same_published_label",source=SOURCE,table="16.5",page=364 if code in {r[0] for r in CAPACITY[:36]} else 365,coverage="Без субъектов малого предпринимательства",note="Не гарантированно доступная мощность; наименования сокращены; сгущённое молоко: изменение названия до 2023 г." if code=="condensed" else "Не гарантированно доступная мощность; наименование сокращено"))
    return assets,capacity

def publish(page,out):
    a,c=records()
    # Do not silently force the national total to match rounded sector values.
    reconciliation=[dict(year=y,official=next(x["stock_mrub"] for x in a if x["code"]=="TOTAL" and x["year"]==y),sum_sections=sum(x["stock_mrub"] for x in a if x["code"]!="TOTAL" and x["year"]==y)) for y in YEARS]
    for row in reconciliation:row["difference_mrub"]=row["sum_sections"]-row["official"]
    data=dict(edition=2025,transcribed="2026-11-24",verification="Текстовые таблицы первоисточника; визуальная сверка страниц недоступна из-за тайм-аута. Ручной снимок.",source=SOURCE,assets=a,capacity=c,reconciliation=reconciliation,
      note="В таблице 14.7 обновление за 2023 год по РФ 4,0%; в таблице 14.3 — 4,1%. Сохранено значение 14.7 для сопоставления по видам деятельности; расхождение не разрешено.")
    (out/"capital-data.json").write_text(json.dumps(data,ensure_ascii=False,allow_nan=False),encoding="utf-8")
    for filename,rows in (("fixed-assets.csv",a),("capacity-utilization.csv",c)):
        with (out/filename).open("w",encoding="utf-8-sig",newline="") as f:
            w=csv.DictWriter(f,fieldnames=list(rows[0]));w.writeheader();w.writerows(rows)
    page("capital.html",'<section class="mast"><p class="kicker">Статистика · производственный потенциал</p><h1>Основные фонды и загрузка мощностей</h1><p>Документальный снимок Российского статистического ежегодника 2025 года: 2022–2024 гг., 19 разделов видов деятельности и выбранные продукты. Не актуальная оценка 2026 года. <a href="'+SOURCE+'">Официальный ежегодник</a> · <a href="https://rosstat.gov.ru/folder/14304">Текущие таблицы фондов</a> · <a href="https://rosstat.gov.ru/enterprise_industrial">Текущие таблицы мощностей</a></p><p><a href="rosstat-workbooks.html">Автоматический импорт и проверка оригинальных файлов Росстата</a></p><p>Текстовая транскрипция, визуальная сверка страниц не удалась из-за тайм-аута. <a href="fixed-assets.csv">Фонды CSV</a> · <a href="capacity-utilization.csv">Мощности CSV</a> · <a href="capital-data.json">JSON</a> · <a href="methodology.html#capital-data-method">Методика</a></p></section><section><h2>Основные фонды по видам деятельности</h2><p>Полная учётная стоимость в смешанных ценах; индекс физического объёма за 2024 г. в сопоставимых ценах. Износ — бухгалтерский показатель, не физическая загрузка. Обновление и выбытие имеют разные знаменатели. В таблице 14.3 за 2023 г. обновление по РФ 4,1%, в 14.7 — 4,0%; здесь сохранена 14.7.</p><label class="capital-control">Год<select id="capital-year"></select></label><label class="capital-control">Сортировка<select id="capital-sort"><option value="wear_pct">Износ</option><option value="stock_mrub">Стоимость</option><option value="renewal_pct">Обновление</option><option value="disposal_pct">Выбытие</option></select></label><p id="capital-status" role="status">Загрузка…</p><div id="capital-metrics" class="metrics"></div><div id="capital-table" class="table-scroll" tabindex="0" role="region" aria-label="Основные фонды"></div><div id="capital-chart"></div><h3>Динамика выбранного вида деятельности</h3><label class="capital-control">Вид деятельности<select id="capital-trend"></select></label><div id="capital-trend-chart"></div></section><section><h2>Использование производственных мощностей по продуктам</h2><p>Без субъектов малого предпринимательства, таблица 16.5. Доля незагруженной среднегодовой мощности = 100 − загрузка. Условный прирост относительно фактического выпуска = (100 / загрузка − 1) × 100. Это арифметический потолок при неизменной мощности и отсутствии других ограничений, а не прогноз или фактический свободный ресурс. Не складывать проценты разных продуктов.</p><label class="capital-control">Год<select id="capacity-year"></select></label><label class="capital-control">Группа<select id="capacity-group"></select></label><label class="capital-control">Поиск продукта<input id="capacity-query" type="search"></label><label class="capital-control">Сортировка<select id="capacity-sort"><option value="high">Сначала высокая загрузка</option><option value="low">Сначала низкая загрузка</option><option value="change">Сначала рост загрузки</option><option value="fall">Сначала снижение загрузки</option><option value="name">По названию</option></select></label><p id="capacity-status" role="status"></p><div id="capacity-distribution"></div><p><button id="capacity-export" type="button" disabled>Выгрузить выбранные продукты CSV</button></p><div id="capacity-table" class="table-scroll" tabindex="0" role="region" aria-label="Загрузка мощностей"></div><div id="capacity-chart"></div><h3>Динамика загрузки выбранного продукта</h3><label class="capital-control">Продукт<select id="capacity-trend"></select></label><div id="capacity-trend-chart"></div><p><a href="scenario.html#dynamic-plan">Сценарная модель</a>: показатели не подставляются автоматически в 19 групп баланса 2021 года, поскольку отличаются год, номенклатура, охват и оценка.</p></section><script defer src="capital-data.js"></script>')
